  "titulo": "Relação entre clock e Q",
  "blocos": [
    {"id": "bloco1", "texto": "Clock ativa a atualização do estado.", "lacuna": false},
    {"id": "bloco2", "texto": "Q muda apenas quando o clock é aplicado.", "lacuna": false},
