  "blocos": [
    {"id": "bloco1", "texto": "Chamada recursiva espera a chamada inferior.", "lacuna": false},
    {"id": "bloco2", "texto": "Quando a chamada inferior termina, ela retorna para a chamada superior.", "lacuna": false},
    {"id": "bloco3", "texto": "O que acontece com a pilha após o retorno?", "lacuna": true}
