}

{
  "modelo": "esquema",
  "titulo": "Papel do clock no flip-flop D",
  "blocos": [
    {
      "id": "bloco1",
      "texto": "Clock atua como gatilho para atualização de Q.",
      "lacuna": false
    },
    {
      "id": "bloco2",
      "texto": "Q muda quando clock muda de nível para borda (ex: subida).",
      "lacuna": true
    },
    {
      "id": "bloco3",
      "texto": "D é capturado durante a borda do clock.",
      "lacuna": false
    }
  ],
  "ligacoes": [
    ["bloco1", "bloco2"],
    ["bloco1", "bloco3"]
  ],
  "destacar": ["bloco2"],
  "pergunta_final": "Qual é a diferença entre latch e flip-flop em relação ao momento de atualização de Q?"
}

{
  "modelo": "esquema",
  "titulo": "Papel do clock no flip-flop D",
  "blocos": [
    {"id": "bloco1", "texto": "Entrada D é o dado a ser armazenado.", "lacuna": false},
    {"id": "bloco2", "texto": "Clock controla quando o dado é transferido para Q.", "lacuna": true},
    {"id": "bloco3", "texto": "Q representa o estado atual do flip-flop.", "lacuna": false}
