  "ligacoes": [["bloco1", "bloco2"], ["bloco2", "bloco3"]],
  "destacar": ["bloco2"],
  "pergunta_final": "Qual é a relação entre o clock e a mudança de Q?"
}

{
  "modelo": "esquema",
  "titulo": "Papel do clock no flip-flop D",
  "blocos": [
    {
      "id": "bloco1",
      "texto": "Clock atua como gatilho para atualização do estado.",
      "lacuna": false
    },
    {
